/*==============================================================
  CineChef - Fase 3c: recetas, tanda 3 de 4
  25 recetas nuevas; no modifica las tandas anteriores.
  Solo utiliza ingredientes cargados en 03b_ingredients.sql.
==============================================================*/
USE CineChefDB;
GO

INSERT INTO dbo.Recipes (Name, Description, PrepMin, Difficulty, Servings)
SELECT source.Name, source.Description, source.PrepMin, source.Difficulty, source.Servings
FROM (VALUES
(N'Kale White Bean Skillet',N'Kale, kidney beans, tomato, garlic, and olive oil become a simple skillet with a rustic Mediterranean spirit. The greens soften into the beans, the sauce stays bright, and every spoonful feels grounding without being heavy, perfect for a quiet supper after a demanding day.',35,1,4),
(N'Chicken Orange Rosemary Traybake',N'Chicken thighs roast with orange, rosemary, carrot, and onion until the edges caramelize and the pan smells warmly citrusy. It is an easy traybake with a golden, welcoming mood, made for evenings when the oven can do the work while everyone settles around the table.',75,2,4),
(N'Shrimp Lime Corn Salad',N'Shrimp, corn, cucumber, lime, and avocado make a cool salad with bright coastal energy. The textures move from juicy to crisp and creamy, while the citrus keeps the dish awake. It is a cheerful lunch for hot days, open windows, and plans that can wait.',25,2,4),
(N'Quinoa Stuffed Bell Peppers',N'Bell peppers filled with quinoa, black beans, corn, tomato, and cheddar bring color and gentle comfort to the table. Baking makes the vegetables sweet and tender, while the grains stay hearty. It is a generous vegetarian supper with a relaxed, optimistic feeling.',65,2,4),
(N'Creamy Tomato Gnocchi Style Pasta',N'Pasta simmered with tomato, cream, basil, garlic, and mozzarella creates a soft, glowing bowl with the ease of a favorite neighborhood restaurant. It is rich but familiar, made for rainy film nights when a comforting meal should arrive warm, fragrant, and uncomplicated.',40,1,4),
(N'Autumn Pear Walnut Salad',N'Pear, walnuts, spinach, feta, and balsamic vinegar make a salad with crisp autumn character. Sweet fruit meets salty cheese and earthy greens, creating a plate that feels thoughtful but effortless. Serve it when the afternoon is cool and the table needs a little brightness.',20,1,4),
(N'Beef Tomato Paprika Stew',N'Beef, tomato, carrot, potato, and paprika simmer slowly into a stew with a deep red color and a patient aroma. It has the reassuring rhythm of a cold-weather kitchen, offering tender bites and a rich broth for evenings when comfort should be substantial.',100,3,6),
(N'Spinach Feta Quinoa Cakes',N'Quinoa cakes hold spinach, feta, eggs, parsley, and black pepper together in crisp little rounds. They feel light but satisfying, with a fresh herbal center and browned edges. This is a relaxed brunch or supper for days when a small, cheerful change of pace sounds good.',40,2,4),
(N'Sesame Cabbage Tofu Bowl',N'Tofu, cabbage, carrot, sesame seeds, and soy sauce make a colorful bowl with savory depth and a gentle crunch. It is quick, balanced, and quietly energizing, the kind of dinner that helps a busy evening feel organized without sacrificing warmth or flavor.',30,1,3),
(N'Baked Cod with Tomato Olive Crust',N'Cod baked with breadcrumbs, tomato, olives, garlic, and lemon develops a crisp, fragrant topping while the fish stays tender beneath it. The dish feels like a small seaside celebration, bright enough for guests and simple enough for a peaceful weeknight.',45,2,4),
(N'Creamy Chicken Mushroom Pasta',N'Chicken, mushrooms, pasta, cream, and thyme come together in a mellow sauce that makes the kitchen feel immediately welcoming. The flavor is savory and familiar, with enough richness for comfort but a gentle finish that suits a quiet dinner and a long conversation.',50,2,4),
(N'Chickpea Avocado Lime Toast',N'Bread topped with chickpeas, avocado, tomato, lime, and chili makes a colorful open sandwich with creamy texture and lively heat. It is fast, filling, and bright enough to rescue a dull lunch, especially when the day needs something fresh without a complicated recipe.',20,1,2),
(N'Pork Apple Cabbage Bowl',N'Pork loin, apple, cabbage, onion, and mustard create a sweet-savory bowl with the cozy character of an autumn market. The cabbage turns silky, the fruit softens into the sauce, and the tender meat makes this an inviting meal for a cool evening at home.',60,2,4),
(N'Roasted Pumpkin Quinoa Pilaf',N'Pumpkin roasted with quinoa, raisins, almonds, cinnamon, and parsley becomes a warm pilaf full of autumn color. Sweet and savory notes meet gently, making the dish feel festive without fuss. It belongs at a generous table where everyone is happy to linger.',55,2,4),
(N'Spicy Anchovy Tomato Spaghetti',N'Anchovies, spaghetti, tomato, garlic, and red chili create a bold pasta with a briny depth and a lively finish. The sauce comes together quickly, filling the room with a Mediterranean aroma. It is ideal for an energetic evening when dinner should have personality.',30,2,3),
(N'Mozzarella Cherry Tomato Frittata',N'Eggs, cherry tomatoes, mozzarella, basil, and spinach bake into a tender frittata with a bright garden flavor. It is soft in the center and lightly golden at the edges, a sunny brunch dish for sharing slowly with coffee, conversation, and no urgent plans.',35,1,4),
(N'Lentil Carrot Coconut Dal',N'Lentils, carrot, coconut milk, curry powder, and spinach simmer into a fragrant dal with a soft, nourishing texture. The spices warm rather than overwhelm, creating a calm bowl for evenings when the mind wants stillness and the body wants something deeply comforting.',50,2,4),
(N'Vegetable Rice Paperless Rolls',N'Lettuce, cucumber, carrot, avocado, and tofu form a crisp bowl inspired by fresh rolls, finished with sesame and lime. It is cool, colorful, and playful to assemble, making a light dinner for warm nights when nobody wants the kitchen to feel crowded.',25,1,3),
(N'Cheddar Cornmeal Breakfast Bake',N'Cornmeal, eggs, cheddar, corn, milk, and onion bake into a tender golden dish with a softly savory aroma. It feels like a relaxed country breakfast, comforting enough for a slow morning and easy to slice for a table full of sleepy, hungry people.',50,1,6),
(N'Salmon Pea Lemon Cakes',N'Salmon cakes with peas, eggs, breadcrumbs, lemon, and parsley are crisp outside, tender inside, and bright with fresh flavor. They feel polished but friendly, suited to a small celebration or a weeknight when everyone could use a dinner that looks more special than it is.',45,2,4),
(N'Mushroom Barleyless Herb Rice',N'Rice, mushrooms, leek, rosemary, and Parmesan create a fragrant side dish with woodland depth and a creamy finish. It is soothing without being sleepy, perfect alongside a simple meal or served alone when a rainy evening calls for something warm and quietly elegant.',40,1,4),
(N'Peanut Banana Honey Toast',N'Bread, peanut butter, banana, honey, cinnamon, and coconut make a warm toast with nostalgic sweetness and a satisfying crunch. It is a quick breakfast or late-night snack that feels generous without effort, especially welcome when comfort matters more than presentation.',15,1,2),
(N'Turkey Kale Tomato Soup',N'Turkey, kale, tomato, carrot, celery, and bay leaves simmer into a clear, savory soup with a homely fragrance. It is light enough for lunch but comforting enough for a cold night, offering the steady feeling of a meal made carefully from ordinary ingredients.',55,1,6),
(N'Warm Peach Cinnamon Couscous',N'Peach, couscous, raisins, cinnamon, honey, and yogurt create a warm bowl that sits between breakfast and dessert. The fruit becomes fragrant as it softens, while the grains keep it satisfying. It feels gentle, sunny, and made for a peaceful morning or a soft ending.',25,1,4),
(N'Squid Tomato Pepper Rice',N'Squid, rice, tomato, bell pepper, garlic, and paprika make a colorful pan with a lively coastal mood. The seafood stays tender when cooked briefly, while the sweet peppers and tomato give the rice a rich base. It is festive, direct, and perfect for sharing.',45,2,4)
) AS source (Name,Description,PrepMin,Difficulty,Servings)
WHERE NOT EXISTS (SELECT 1 FROM dbo.Recipes AS target WHERE target.Name=source.Name);
GO

