GO

SELECT N'Recipes' AS Catalog,COUNT(*) AS ItemCount,MIN(LEN(Description)) AS MinDescriptionLength,MAX(LEN(Description)) AS MaxDescriptionLength
FROM dbo.Recipes WHERE Name IN (N'Kale White Bean Skillet',N'Chicken Orange Rosemary Traybake',N'Shrimp Lime Corn Salad',N'Quinoa Stuffed Bell Peppers',N'Creamy Tomato Gnocchi Style Pasta',N'Autumn Pear Walnut Salad',N'Beef Tomato Paprika Stew',N'Spinach Feta Quinoa Cakes',N'Sesame Cabbage Tofu Bowl',N'Baked Cod with Tomato Olive Crust',N'Creamy Chicken Mushroom Pasta',N'Chickpea Avocado Lime Toast',N'Pork Apple Cabbage Bowl',N'Roasted Pumpkin Quinoa Pilaf',N'Spicy Anchovy Tomato Spaghetti',N'Mozzarella Cherry Tomato Frittata',N'Lentil Carrot Coconut Dal',N'Vegetable Rice Paperless Rolls',N'Cheddar Cornmeal Breakfast Bake',N'Salmon Pea Lemon Cakes',N'Mushroom Barleyless Herb Rice',N'Peanut Banana Honey Toast',N'Turkey Kale Tomato Soup',N'Warm Peach Cinnamon Couscous',N'Squid Tomato Pepper Rice');
SELECT N'RecipeIngredients' AS Catalog,COUNT(*) AS ItemCount FROM dbo.RecipeIngredients AS ri JOIN dbo.Recipes AS r ON r.RecipeId=ri.RecipeId WHERE r.Name IN (N'Kale White Bean Skillet',N'Chicken Orange Rosemary Traybake',N'Shrimp Lime Corn Salad',N'Quinoa Stuffed Bell Peppers',N'Creamy Tomato Gnocchi Style Pasta',N'Autumn Pear Walnut Salad',N'Beef Tomato Paprika Stew',N'Spinach Feta Quinoa Cakes',N'Sesame Cabbage Tofu Bowl',N'Baked Cod with Tomato Olive Crust',N'Creamy Chicken Mushroom Pasta',N'Chickpea Avocado Lime Toast',N'Pork Apple Cabbage Bowl',N'Roasted Pumpkin Quinoa Pilaf',N'Spicy Anchovy Tomato Spaghetti',N'Mozzarella Cherry Tomato Frittata',N'Lentil Carrot Coconut Dal',N'Vegetable Rice Paperless Rolls',N'Cheddar Cornmeal Breakfast Bake',N'Salmon Pea Lemon Cakes',N'Mushroom Barleyless Herb Rice',N'Peanut Banana Honey Toast',N'Turkey Kale Tomato Soup',N'Warm Peach Cinnamon Couscous',N'Squid Tomato Pepper Rice');
GO
